const uint8_t *data = static_cast<const uint8_t*>(buffer);
lfs_size_t diff = 0;

while (size > 0) {
    lfs_size_t chunk = lfs_min(size, hint);

    uint8_t *rcache_buffer = nullptr;
    int err = lfs_bd_read(lfs, pcache, rcache, hint, block, off, &rcache_buffer, chunk);
    if (err) {
        return err;
    }

    int cmp = std::memcmp(rcache_buffer, data, chunk);
    if (cmp != 0) {
        return cmp < 0 ? LFS_CMP_LT : LFS_CMP_GT;
    }

    data   += chunk;
    off    += chunk;
    size   -= chunk;
}

return LFS_CMP_EQ;

